struct SiteRecipe {
    prompt_tokens: usize,
    call: usize,
    node: usize,
    packets: &'static [fn() -> Packet],
    copy_output: Option<usize>,
}

fn materialize_sites(recipes: &[SiteRecipe]) -> Result<Vec<Site>> {
    let mut sites = Vec::with_capacity(recipes.len());
    for recipe in recipes {
        if !matches!(recipe.prompt_tokens, 47..=50) || recipe.call != 0 {
            return Err(Error::Unsupported(
                "fresh-prefill captured call unavailable".into(),
            ));
        }
        sites.push(Site {
            key: Key {
                prompt_tokens: recipe.prompt_tokens,
                call: recipe.call,
                node: recipe.node,
            },
            packets: recipe.packets.iter().map(|factory| factory()).collect(),
            copy_output: recipe.copy_output,
        });
    }
    Ok(sites)
}

