pub(crate) const METADATA_BYTES: usize = 5 * 1024 * 1024;

pub(crate) fn sites(capture: TextKernelCapture) -> Result<Vec<Site>> {
    if !capture.is_fresh_prefill() {
        return Err(Error::Unsupported("fresh-prefill capture required".into()));
    }
    materialize_sites(QWEN08_FRESH_PREFILL_SITES)
}

const PRIVATE: &[(Role, usize)] = &[
    (Role::Lse, 1504),
    (Role::Lse, 1536),
    (Role::Lse, 1568),
    (Role::Lse, 1600),
];

pub(crate) fn private_layout(capture: TextKernelCapture) -> Result<&'static [(Role, usize)]> {
    if !capture.is_fresh_prefill() {
        return Err(Error::Unsupported("fresh-prefill capture required".into()));
    }
    Ok(PRIVATE)
}
